                  (click)="addProof(c)"
                >
                  Add proof
                </button>
                <label class="visually-hidden" [for]="'claim-defer-date-' + c.id">Defer until</label>
                <input
                  [id]="'claim-defer-date-' + c.id"
                  type="date"
                  data-testid="claim-defer-date"
                  [value]="deferDates().get(c.id) ?? ''"
                  (input)="deferDateChange(c.id, $any($event.target).value)"
                />
                <button
