79	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, claim));
80	        rollup.recordChanges(user, sheetId, before);
81	        return claim;
82	    }
83	
84	    /** Edit a claim; only a draft can be edited (an open claim is voided and added again instead), and one dated
85	     * in a closed period, or that would be, is refused, as is a correction that does not name a settled claim of
86	     * the same person. */
87	    @Transactional
88	    public Claim update(String user, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
89	            String corrects) {
90	        LocalDate today = sheets.today(sheetId);
91	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
92	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
93	        if (claim.getStatus() != ClaimStatus.DRAFT) {
94	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
95	        }
96	        requireOpenPeriod(sheetId, claim.getDate());
97	        requireOpenPeriod(sheetId, date != null ? date : today);
98	        requireNotRetired(requirePerson(sheetId, claim.getPersonId()), date != null ? date : today);
99	        String corrected = correctedBy(sheetId, claim.getPersonId(), amount, corrects);
100	        Snapshot before = rollup.snapshot(sheetId);
101	        claim.setAmount(amount);
102	        claim.setCorrects(corrected);
103	        claim.setDate(date != null ? date : today);
104	        claim.setNote(noteOf(note));
105	        claims.flush();
106	        audit.recordOnCommit(entry("CLAIM_EDITED", user, requirePerson(sheetId, claim.getPersonId()), claim));
107	        rollup.recordChanges(user, sheetId, before);
108	        return claim;
109	    }
110	
111	    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
112	     * period, is refused. A settle by a clerk of a claim whose due is above the clerk limit sends it PENDING a
113	     * steward instead. */
114	    @Transactional
115	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
116	        sheets.today(sheetId); // the sheet must exist
117	        // Locking the sheet before taking the number opens claims one at a time; a refused open rolls back
118	        // and gives the number back.
119	        if (next == ClaimStatus.OPEN) {
120	            sheets.lock(sheetId);
121	        }
122	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
123	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
124	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : null;
125	        requireOpenPeriod(sheetId, claim.getDate());
126	        if (!claim.getStatus().canBecome(next)) {
127	            throw new ResponseStatusException(HttpStatus.CONFLICT,
128	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
129	        }
130	        // Only a role the sheet's permission matrix allows may open, settle or void a claim.
131	        settings.requirePermitted(sheetId, user, PERMISSIONS.get(next));
132	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
133	        if (next == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
136	        }
137	        // Four eyes: whoever opened a claim cannot also settle it.
138	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
139	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
140	        }
141	        Person person = requirePerson(sheetId, claim.getPersonId());
142	        BigDecimal due = rollup.dueOf(claim, person);
143	        // A claim whose due is above the proof threshold in force on its date needs a proof before it is settled,
144	        // whoever settles it, so it never goes PENDING without one.
145	        if (next == ClaimStatus.SETTLED) {
146	            settings.requireProof(sheetId, claim.getDate(), due, claim.getProofs());
147	        }
148	        // A clerk settles only a claim whose due is within the sheet's clerk limit; above it, a steward must
149	        // approve it.
150	        if (next == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, due)) {
151	            next = ClaimStatus.PENDING;
152	        }
153	        Snapshot before = rollup.snapshot(sheetId);
154	        claim.setStatus(next);
155	        if (next == ClaimStatus.OPEN) {
156	            claim.setNumber(number);
157	            claim.setOpenedBy(user);
158	        }
159	        // A voided claim's line carries the number it had.
160	        String entry = entry(EVENTS.get(next), user, person, claim);
161	        if (next == ClaimStatus.SETTLED) {
162	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
163	            // the rate its grade has on its date; with no figure it stays live. The late charge it has (taken
164	            // while it is still OPEN) is frozen in.
165	            entry += settle(claim, due);
166	        }
167	        logStatus(user, sheets.today(sheetId), claim, person);
168	        claims.flush();
169	        audit.recordOnCommit(entry);
170	        rollup.recordChanges(user, sheetId, before);
171	        return claim;
172	    }
173	
174	    /** A steward approves a PENDING claim: it is SETTLED at the due it has now, its live figure with any late
175	     * charge, frozen. The user who opened it cannot approve it, and one whose due is above the proof threshold
176	     * in force on its date cannot be approved while it has no proof. */
177	    @Transactional
178	    public Claim approve(String user, String sheetId, Long id) {
179	        Claim claim = requirePending(user, sheetId, id);
180	        if (user.equals(claim.getOpenedBy())) {
181	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it.");
182	        }
183	        Person person = requirePerson(sheetId, claim.getPersonId());
184	        Snapshot before = rollup.snapshot(sheetId);
185	        BigDecimal due = rollup.dueOf(claim, person);
186	        settings.requireProof(sheetId, claim.getDate(), due, claim.getProofs());
187	        claim.setStatus(ClaimStatus.SETTLED);
188	        String entry = entry("CLAIM_APPROVED", user, person, claim) + settle(claim, due);
189	        logStatus(user, sheets.today(sheetId), claim, person);
190	        claims.flush();
191	        audit.recordOnCommit(entry);
192	        rollup.recordChanges(user, sheetId, before);
193	        return claim;
194	    }
195	
196	    /** A steward re-settles a SETTLED claim: it is frozen again at the figure it would have today as an OPEN
197	     * claim bound by no statement, at today's rates, grades, floor and late charge. Refused for anyone else, a
198	     * claim of any other status, or one dated in a closed period. */
199	    @Transactional
200	    public Claim resettle(String user, String sheetId, Long id) {
201	        sheets.today(sheetId); // the sheet must exist
202	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
203	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
204	        requireOpenPeriod(sheetId, claim.getDate());
205	        if (claim.getStatus() != ClaimStatus.SETTLED) {
206	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled.");
207	        }
208	        settings.requireSteward(sheetId, user);
209	        Person person = requirePerson(sheetId, claim.getPersonId());
210	        Snapshot before = rollup.snapshot(sheetId);
211	        BigDecimal old = rollup.dueOf(claim, person);
212	        BigDecimal now = rollup.openDueOf(claim, person);
213	        claim.setSettledDue(now);
214	        logStatus(user, sheets.today(sheetId), claim, person);
215	        claims.flush();
216	        audit.recordOnCommit(entry("CLAIM_RESETTLED", user, person, claim) + " old=" + figure(old) + " new="
217	                + figure(now));
218	        rollup.recordChanges(user, sheetId, before);
219	        return claim;
220	    }
221	
222	    /** A figure with two decimals, or n/a. */
223	    private static String figure(BigDecimal due) {
224	        return due != null ? due.setScale(2).toPlainString() : "n/a";
225	    }
226	
227	    /** Defer an OPEN claim until a date after the sheet's today: until then it counts in no total, is not overdue,
228	     * cannot be settled and is left unbound by a statement. A claim that is not OPEN, a date not after today, or
229	     * a claim dated in a closed period, is refused. */
230	    @Transactional
231	    public Claim defer(String user, String sheetId, Long id, LocalDate until) {
232	        LocalDate today = sheets.today(sheetId);
233	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
234	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
235	        requireOpenPeriod(sheetId, claim.getDate());
236	        if (claim.getStatus() != ClaimStatus.OPEN) {
237	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be deferred.");
238	        }
239	        if (!until.isAfter(today)) {
240	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A claim is deferred to a date after today.");
241	        }
242	        Person person = requirePerson(sheetId, claim.getPersonId());
243	        Snapshot before = rollup.snapshot(sheetId);
244	        claim.setDeferredUntil(until);
245	        claims.flush();
246	        audit.recordOnCommit(entry("CLAIM_DEFERRED", user, person, claim) + " until=" + until);
247	        rollup.recordChanges(user, sheetId, before);
248	        return claim;
249	    }
250	
251	    /** Raise a claim's proofs count by one; a SETTLED or VOID claim, or one dated in a closed period, is
252	     * refused. */
253	    @Transactional
254	    public Claim addProof(String user, String sheetId, Long id) {
255	        sheets.today(sheetId); // the sheet must exist
256	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
257	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
258	        requireOpenPeriod(sheetId, claim.getDate());
259	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
260	            throw new ResponseStatusException(HttpStatus.CONFLICT,
261	                    "A " + claim.getStatus() + " claim cannot take a proof.");
262	        }
263	        Person person = requirePerson(sheetId, claim.getPersonId());
264	        claim.addProof();
265	        claims.flush();
266	        audit.recordOnCommit(entry("CLAIM_PROOF_ADDED", user, person, claim) + " proofs=" + claim.getProofs());
267	        return claim;
268	    }
269	
270	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by its person's last
271	     * statement if that statement included it. */
272	    @Transactional
273	    public Claim reject(String user, String sheetId, Long id, String reason) {
274	        Claim claim = requirePending(user, sheetId, id);
275	        Person person = requirePerson(sheetId, claim.getPersonId());
276	        Snapshot before = rollup.snapshot(sheetId);
277	        claim.setStatus(ClaimStatus.OPEN);
278	        logStatus(user, sheets.today(sheetId), claim, person);
279	        claims.flush();
280	        audit.recordOnCommit(entry("CLAIM_REJECTED", user, person, claim) + " reason=" + reason.trim());
281	        rollup.recordChanges(user, sheetId, before);
282	        return claim;
283	    }
284	
285	    /** A user whose role may reassign (a steward by the standing rule) moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
286	     * date but loses any figure a statement bound it to: it is live again until its new person's next statement.
287	     * One dated in a closed period, a correction (which names a settled claim of its own person), or one dated
288	     * after its new person is retired, is refused. */
289	    @Transactional
290	    public Claim reassign(String user, String sheetId, Long id, Long toPersonId) {
291	        sheets.today(sheetId); // the sheet must exist
292	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
293	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
294	        settings.requirePermitted(sheetId, user, Permission.REASSIGN);
295	        requireOpenPeriod(sheetId, claim.getDate());
296	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
297	            throw new ResponseStatusException(HttpStatus.CONFLICT,
298	                    "A " + claim.getStatus() + " claim cannot be moved.");
299	        }
300	        if (claim.isCorrection()) {
301	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A correction cannot be moved.");
302	        }
303	        Person from = requirePerson(sheetId, claim.getPersonId());
304	        Person to = requirePerson(sheetId, toPersonId);
305	        if (from.getId().equals(to.getId())) {
306	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's.");
307	        }
308	        if (to.retiredOn(claim.getDate())) {
309	            throw new ResponseStatusException(HttpStatus.GONE,
310	                    to.getName() + " is retired from " + to.getRetiredFrom() + ".");
311	        }
312	        Snapshot before = rollup.snapshot(sheetId);
313	        claim.setPersonId(to.getId());
314	        claim.unbind();
315	        claims.flush();
316	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, claim) + " from=" + from.getName() + " to="
317	                + to.getName());
318	        rollup.recordChanges(user, sheetId, before);
319	        return claim;
320	    }
321	
322	    /** The PENDING claim a steward acts on; refused when it is not on the sheet, not PENDING, dated in a closed
323	     * period, or the user is not a steward. */
324	    private Claim requirePending(String user, String sheetId, Long id) {
325	        sheets.today(sheetId); // the sheet must exist
326	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
327	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
328	        requireOpenPeriod(sheetId, claim.getDate());
329	        if (claim.getStatus() != ClaimStatus.PENDING) {
330	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
331	        }
332	        settings.requireSteward(sheetId, user);
333	        return claim;
334	    }
335	
336	    /** Log the status a claim has now, by the user on the sheet's today, with its due as computed now. */
337	    private void logStatus(String user, LocalDate today, Claim claim, Person person) {
338	        BigDecimal due = rollup.dueOf(claim, person);
339	        claim.logStatus(user, today, due != null ? due.setScale(2).toPlainString() : "n/a");
340	    }
341	
342	    /** Fix a claim's due at the given figure (none stays live), giving the end of its audit line. */
343	    private static String settle(Claim claim, BigDecimal due) {
344	        claim.setSettledDue(due);
345	        return " due=" + (due != null ? due.toPlainString() : "n/a");
346	    }
347	
348	    /** What opening (or settling) claims together did: how many went through and were refused, and the claims
349	     * that went through. */
350	    public record OpenedAll(int opened, int refused, List<Claim> claims) {}
351	
352	    /** Open the given claims of the sheet one at a time, in list order: people in the order they were added,
353	     * each one's claims newest first. Each is opened, and numbered, as {@link #changeStatus} would open it on its
354	     * own; one that cannot be opened (or is not on the sheet) is refused and left as it is. */
355	    public OpenedAll openAll(String user, String sheetId, List<Long> ids) {
356	        return changeAll(user, sheetId, ids, ClaimStatus.OPEN);
357	    }
358	
359	    /** Settle the given claims of the sheet one at a time, in list order, each as {@link #changeStatus} would
360	     * settle it on its own: one a clerk sends PENDING counts as settled; one that cannot be settled (or is not on
361	     * the sheet) is refused and left as it is. */
362	    public OpenedAll settleAll(String user, String sheetId, List<Long> ids) {
363	        return changeAll(user, sheetId, ids, ClaimStatus.SETTLED);
364	    }
365	
366	    /** Move the given claims to a status one at a time, in list order: people in the order they were added, each
367	     * one's claims newest first, each in its own transaction; one that is refused is left as it is. */
368	    private OpenedAll changeAll(String user, String sheetId, List<Long> ids, ClaimStatus next) {
369	        Set<Long> wanted = new HashSet<>(ids);
370	        List<Claim> chosen = transaction.execute(status -> {
371	            sheets.today(sheetId); // the sheet must exist
372	            Map<Long, Integer> personOrder = new HashMap<>();
373	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
374	                personOrder.put(person.getId(), personOrder.size());
375	            }
376	            return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
377	                    .filter(c -> wanted.contains(c.getId()))
378	                    .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
379	                    .toList();
380	        });
381	        List<Claim> changed = new ArrayList<>();
382	        if (settings.roleOf(sheetId, user) == Role.VIEWER) {
383	            // A viewer changes nothing: every claim is refused.
384	            return new OpenedAll(0, wanted.size(), changed);
385	        }
386	        for (Claim claim : chosen) {
387	            try {
388	                changed.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), next)));
389	            } catch (ResponseStatusException refused) {
390	                // Left as it is: its transaction rolled back, writing nothing.
391	            }
392	        }
393	        return new OpenedAll(changed.size(), wanted.size() - changed.size(), changed);
394	    }
395	
396	    /** The sequence a claim in no period is numbered in, with period numbering. */
397	    private static final String NO_PERIOD = "X";
398	
399	    /** The action of the permission matrix each status a claim is moved to takes. */
400	    private static final Map<ClaimStatus, Permission> PERMISSIONS = Map.of(
401	            ClaimStatus.OPEN, Permission.OPEN,
402	            ClaimStatus.SETTLED, Permission.SETTLE,
403	            ClaimStatus.VOID, Permission.VOID);
404	
405	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
406	            ClaimStatus.OPEN, "CLAIM_OPENED",
407	            ClaimStatus.PENDING, "CLAIM_PENDING",
408	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
409	            ClaimStatus.VOID, "CLAIM_VOIDED");
410	
411	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
412	     * else what is due at the rate of the grade its person has on its date; none when that is n/a. */
413	    public BigDecimal figureOf(Claim claim, Person person) {
414	        return rollup.figureOf(claim, person);
415	    }
416	
417	    /** The number a claim opened now takes: the sheet's next number or, with period numbering in force, the next
418	     * in its period's own sequence, <period name>-<n>, or X-<n> for a claim in no period. */
419	    private String nextNumber(String sheetId, Claim claim) {
420	        if (!sheets.numbersByPeriod(sheetId)) {
421	            return String.valueOf(sheets.nextClaimNumber(sheetId));
422	        }
423	        String prefix = periods.periodOf(sheetId, claim.getDate()).map(Period::getName).orElse(NO_PERIOD) + "-";
424	        int last = 0;
425	        for (Claim other : claims.findBySheetIdOrderByIdDesc(sheetId)) {
426	            String number = other.getNumber();
427	            if (number != null && number.startsWith(prefix)) {
428	                String rest = number.substring(prefix.length());
429	                if (rest.matches("\\d{1,9}")) {
430	                    last = Math.max(last, Integer.parseInt(rest));
431	                }
432	            }
433	        }
434	        return prefix + (last + 1);
435	    }
436	
437	    /** The number a claim of this amount corrects: none unless the amount is negative, when it must name a
438	     * SETTLED claim of the same person, or the claim is refused. */
439	    private String correctedBy(String sheetId, Long personId, BigDecimal amount, String corrects) {
440	        if (amount.signum() >= 0) {
441	            return null;
442	        }
443	        String named = corrects == null ? null : corrects.trim();
444	        boolean settled = named != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
445	                .anyMatch(c -> named.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
446	        if (!settled) {
447	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
448	                    "A correction must name a settled claim of the same person.");
449	        }
450	        return named;
451	    }
452	
453	    /** Refuse a change to a claim dated in a closed period. Locks the sheet first, so a period cannot close
454	     * while the change is made. */
455	    private void requireOpenPeriod(String sheetId, LocalDate date) {
456	        sheets.lock(sheetId);
457	        periods.requireOpen(sheetId, date);
458	    }
459	
460	    /** Refuse a claim dated after its person's retirement. */
461	    private static void requireNotRetired(Person person, LocalDate date) {
462	        if (person.retiredOn(date)) {
463	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
464	                    person.getName() + " is retired from " + person.getRetiredFrom() + ".");
465	        }
466	    }
467	
468	    private Person requirePerson(String sheetId, Long personId) {
469	        return people.findByIdAndSheetId(personId, sheetId)
470	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
471	    }
472	
473	    /** The amount is written as the screen shows it, with two decimals; the date as yyyy-mm-dd; a
474	     * claim with a number ends with it. */
475	    private static String entry(String event, String user, Person person, Claim claim) {
476	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
477	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
478	                + (claim.getNumber() != null ? " number=" + claim.getNumber() : "");
479	    }
480	
481	    private static String noteOf(String note) {
482	        return note == null ? "" : note.trim();
483	    }
484	}
